{
  "categoryId": "{{catId}}",
  "listingType": "SELL",
  "version": 1,
  "isActive": true,
  "title": {
    "en": "List Vegetables & Fruits",
    "hi": "सब्ज़ियाँ और फल सूचीबद्ध करें"
  },
  "fields": [
    {
      "fieldKey": "type",
      "type": "RADIO",
      "label": {
        "en": "Type",
        "hi": "प्रकार"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": true,
      "displayOrder": 10,
      "optionSetKey": "veg_fruit__vf_type",
      "editableOnUpdate": false
    },
    {
      "fieldKey": "vegetableName",
      "type": "DROPDOWN",
      "label": {
        "en": "Vegetable Name",
        "hi": "सब्ज़ी का नाम"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 20,
      "optionSetKey": "veg_fruit__vegetable_name",
      "allowOther": true,
      "editableOnUpdate": false,
      "visibleWhen": {
        "field": "type",
        "operator": "equals",
        "value": "vegetables"
      }
    },
    {
      "fieldKey": "vegetableNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify",
        "hi": "कृपया निर्दिष्ट करें"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 30,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "vegetableName",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "fruitName",
      "type": "DROPDOWN",
      "label": {
        "en": "Fruit Name",
        "hi": "फल का नाम"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 40,
      "optionSetKey": "veg_fruit__fruit_name",
      "allowOther": true,
      "editableOnUpdate": false,
      "visibleWhen": {
        "field": "type",
        "operator": "equals",
        "value": "fruit"
      }
    },
    {
      "fieldKey": "fruitNameOther",
      "type": "TEXT",
      "label": {
        "en": "Please Specify",
        "hi": "कृपया निर्दिष्ट करें"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 50,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      },
      "visibleWhen": {
        "field": "fruitName",
        "operator": "equals",
        "value": "__other__"
      }
    },
    {
      "fieldKey": "variety",
      "type": "TEXT",
      "label": {
        "en": "Variety",
        "hi": "किस्म"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 60,
      "fieldLength": 80,
      "validation": {
        "maxLength": 80
      }
    },
    {
      "fieldKey": "quality",
      "type": "RADIO",
      "label": {
        "en": "Quality",
        "hi": "गुणवत्ता"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 70,
      "optionSetKey": "veg_fruit__vf_quality"
    },
    {
      "fieldKey": "isOrganic",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Organic?",
        "hi": "क्या जैविक है?"
      },
      "sectionKey": "details",
      "sectionTitle": {
        "en": "Details",
        "hi": "विवरण"
      },
      "required": false,
      "displayOrder": 80
    },
    {
      "fieldKey": "quantity",
      "type": "NUMBER",
      "label": {
        "en": "Quantity",
        "hi": "मात्रा"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 90,
      "inlineEditable": true,
      "validation": {
        "min": 1
      }
    },
    {
      "fieldKey": "unit",
      "type": "DROPDOWN",
      "label": {
        "en": "Unit",
        "hi": "इकाई"
      },
      "sectionKey": "quantity",
      "sectionTitle": {
        "en": "Quantity & Unit",
        "hi": "मात्रा और इकाई"
      },
      "required": true,
      "displayOrder": 100,
      "optionSetKey": "veg_fruit__vf_unit"
    },
    {
      "fieldKey": "actualPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Actual Price (₹)",
        "hi": "वास्तविक मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 110,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "offeredPrice",
      "type": "DECIMAL",
      "label": {
        "en": "Offered Price (₹)",
        "hi": "प्रस्तावित मूल्य (₹)"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": true,
      "displayOrder": 120,
      "common": true,
      "inlineEditable": true,
      "validation": {
        "min": 0
      }
    },
    {
      "fieldKey": "discountPct",
      "type": "AUTO_CALC",
      "label": {
        "en": "Discount %",
        "hi": "छूट %"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 130,
      "common": true,
      "readOnly": true,
      "computed": {
        "formula": "(actualPrice - offeredPrice) / actualPrice * 100",
        "readOnly": true
      }
    },
    {
      "fieldKey": "isNegotiable",
      "type": "BOOLEAN",
      "label": {
        "en": "Is Negotiable?",
        "hi": "क्या मोल-भाव योग्य है?"
      },
      "sectionKey": "pricing",
      "sectionTitle": {
        "en": "Pricing",
        "hi": "मूल्य निर्धारण"
      },
      "required": false,
      "displayOrder": 140,
      "common": true
    },
    {
      "fieldKey": "images",
      "type": "IMAGE",
      "label": {
        "en": "Upload Images",
        "hi": "तस्वीरें अपलोड करें"
      },
      "sectionKey": "media",
      "sectionTitle": {
        "en": "Photos",
        "hi": "तस्वीरें"
      },
      "required": true,
      "displayOrder": 150,
      "multiple": true,
      "common": true,
      "validation": {
        "min": 1,
        "max": 10,
        "acceptedTypes": [
          "jpg",
          "png",
          "webp"
        ],
        "sources": [
          "camera",
          "gallery"
        ],
        "capture": true
      }
    },
    {
      "fieldKey": "contactNumber",
      "type": "TEXT",
      "label": {
        "en": "Contact Number",
        "hi": "संपर्क नंबर"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": true,
      "displayOrder": 160,
      "common": true,
      "fieldLength": 10,
      "validation": {
        "regex": "^[6-9][0-9]{9}$",
        "maxLength": 10
      }
    },
    {
      "fieldKey": "showContact",
      "type": "BOOLEAN",
      "label": {
        "en": "Show my contact number & address to buyers",
        "hi": "मेरा संपर्क नंबर और पता खरीदारों को दिखाएं"
      },
      "sectionKey": "contact",
      "sectionTitle": {
        "en": "Contact",
        "hi": "संपर्क"
      },
      "required": false,
      "displayOrder": 170,
      "help": {
        "en": "If off, your number and full address stay hidden — buyers must send a contact request that you approve before they are revealed.",
        "hi": "यदि बंद है, तो आपका नंबर और पूरा पता छिपा रहेगा — खरीदार संपर्क अनुरोध भेजेंगे और आपकी स्वीकृति के बाद ही ये दिखेंगे।"
      },
      "common": true
    }
  ]
}

